{
  "a_requests": [
    {
      "a_request": "R1",
      "b_asked": "공영주차장에 오래 세우면 시간제로 계속 돈이 올라가는지 여부",
      "c_basis": "APPLIED",
      "d_claims": [
        {
          "a_text": "서울특별시 주차장 설치 및 관리 조례 별표 1 비고3에 따르면, 시간제 주차요금이 1일 주차요금을 초과하는 경우에는 1일 주차요금을 받는다. 따라서 오래 세워 시간제 요금이 1일 주차요금에 도달하면 그 이후부터는 계속 시간제로 올라가지 않고 1일 주차요금만 받는다.",
          "b_ids": "주차장:별표1#비고3"
        }
      ],
      "e_status": "ANSWERED"
    },
    {
      "a_request": "R2",
      "b_asked": "개별 주차장의 하루 요금이 한 시간 요금의 몇 배인지, 시간요금이 그 금액을 넘으면 어떻게 받는지",
      "c_basis": "DIRECT",
      "d_claims": [
        {
          "a_text": "별표 1 비고3은 개별주차장 1일 주차요금은 1시간 환산요금의 6배를 적용하며, 시간제 주차요금이 1일 주차요금을 초과하는 경우에는 1일 주차요금을 받는다고 정하고 있다.",
          "b_ids": "주차장:별표1#비고3"
        }
      ],
      "e_status": "ANSWERED"
    }
  ]
}
